CREATE TABLE npc_diary_entries ( -- 小日记表
  row_id INTEGER PRIMARY KEY, -- 行号
  diary_date TEXT NOT NULL CHECK(TRIM(diary_date) <> '' AND diary_date GLOB '*-*-*'), -- 日期
  character_name TEXT NOT NULL CHECK(TRIM(character_name) <> ''), -- 角色
  diary_content TEXT NOT NULL CHECK(TRIM(diary_content) <> '') -- 内容
);

sourceData.updateNode:
每轮都要更新：上轮场景时间、经过的时间、当前时间。位置有变就更新对应地点字段。current_location、current_minor_region、current_major_region、elapsed_time、cur_time 均 NOT NULL，不能写成 NULL 或空串。cur_time / prev_scene_time 必须严格是 'YYYY-MM-DD HH:MM' 格式。
SQL示例(纯时间推进): UPDATE global_state SET prev_scene_time = '2024-04-01 09:00', elapsed_time = '3小时20分', cur_time = '2024-04-01 12:20' WHERE row_id = 1;
SQL示例(含位置变动): UPDATE global_state SET current_location = '御苑', current_minor_region = '新宿区', current_major_region = '东京都', prev_scene_time = '2024-04-01 12:20', elapsed_time = '1小时', cur_time = '2024-04-01 13:20' WHERE row_id = 1;

已存在的这一行，字段值变化时更新：年龄、外貌、身份、状态、位置、属性、资源。位置变化时建议同步补世界地图点表。self_status、location_name、appearance、identity_text、base_attributes、name、gender、age 均 NOT NULL，不能写成 NULL 或空串。
SQL示例(状态变化): UPDATE protagonist_info SET self_status = '疲劳,轻伤', location_name = '御苑' WHERE row_id = 1;
SQL示例(属性变化): UPDATE protagonist_info SET base_attributes = '力量:58; 敏捷:60; 体质:55; 智力:63; 感知:62; 魅力:56', special_attributes = '爆裂魔法:75' WHERE row_id = 1;
SQL示例(资源变化): UPDATE protagonist_info SET resources_text = '金币:180; 行动点:2' WHERE row_id = 1;

已存在的角色，字段值变化时更新：外貌、身份、属性、位置、在场状态、人际关系、重大经历。过往经历字数接近上限时压缩重写。presence_status='离场' 时 interaction_options 可为 NULL；='在场' 时 interaction_options 必须是非空字符串。
SQL示例(进入场景): UPDATE important_npc SET location_name = '御苑', presence_status = '在场', interaction_options = '交谈,告别' WHERE name = '艾莉丝';
SQL示例(离开场景): UPDATE important_npc SET presence_status = '离场', interaction_options = NULL WHERE name = '艾莉丝';
SQL示例(关系/属性变化): UPDATE important_npc SET relations_text = '主角:恋人', base_attributes = '力量:40; 敏捷:54; 体质:46; 智力:73; 感知:70; 魅力:62' WHERE name = '艾莉丝';

